      PRIORITY = 1;
      ACTIVATION = 1;
      SCHEDULE = FULL;
      AUTOSTART = TRUE;
      STACK = SHARED;
    };
    COUNTER Counter1 {
      MINCYCLE = 2;
      MAXALLOWEDVALUE = 16 ;
      TICKSPERBASE = 1;
    };
