*** EE_UINT16 EE_timer_get_counter() // get counter
*** void EE_timer_enable_ISR(EE_UINT16 tim_id, EE_UINT8 isr_mode) // enable IRQ
** void EE_timer_disable_ISR(EE_UINT16 tim_id) // disable IRQ

